From 82e4a9cc8b0ced3ed6cf49c8b4f0238b0179abee Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:56:06 +0100
Subject: [PATCH] applets/calendar: support calendar add-ons like the Digital
 Clock

The standalone Calendar widget had no way to show an alternate calendar,
holidays or astronomical events. It now has the same add-ons list and
pages as the Digital Clock, and shows the selected day's alternate date.

BUG: 472750
---
 applets/calendar/main.xml              |  4 ++
 applets/calendar/qml/config.qml        | 35 ++++++++++++
 applets/calendar/qml/configGeneral.qml | 74 +++++++++++++++++++++++++-
 applets/calendar/qml/main.qml          |  7 +++
 components/calendar/qml/MonthView.qml  |  4 +-
 5 files changed, 120 insertions(+), 4 deletions(-)

diff --git a/applets/calendar/main.xml b/applets/calendar/main.xml
index 728ac4e6c3..4228d7e4f0 100644
--- a/applets/calendar/main.xml
+++ b/applets/calendar/main.xml
@@ -18,5 +18,9 @@
     <entry name="compactDisplay" type="String">
         <default>d</default>
     </entry>
+    <entry name="enabledCalendarPlugins" type="StringList">
+      <label>A list of plugins where additional calendar event data can be sourced.</label>
+      <default></default>
+    </entry>
   </group>
 </kcfg>
diff --git a/applets/calendar/qml/config.qml b/applets/calendar/qml/config.qml
index 24ea795d47..1258681852 100644
--- a/applets/calendar/qml/config.qml
+++ b/applets/calendar/qml/config.qml
@@ -4,14 +4,49 @@
     SPDX-License-Identifier: GPL-2.0-only OR GPL-3.0-only OR LicenseRef-KDE-Accepted-GPL
 */

+pragma ComponentBehavior: Bound
+
 import QtQuick

+import org.kde.plasma.plasmoid
 import org.kde.plasma.configuration
+import org.kde.plasma.workspace.calendar as PlasmaCalendar

 ConfigModel {
+    id: configModel
+
     ConfigCategory {
          name: i18n("General")
          icon: "preferences-desktop-plasma"
          source: "configGeneral.qml"
     }
+
+    readonly property PlasmaCalendar.EventPluginsManager eventPluginsManager: PlasmaCalendar.EventPluginsManager {
+        Component.onCompleted: {
+            populateEnabledPluginsList(Plasmoid.configuration.enabledCalendarPlugins);
+        }
+    }
+
+    readonly property Instantiator __eventPlugins: Instantiator {
+        model: configModel.eventPluginsManager.model
+        delegate: ConfigCategory {
+            required property string display
+            required property string decoration
+            required property string configUi
+            required property string configModule
+            required property string configComponent
+            required property string pluginId
+
+            name: display
+            icon: decoration
+            source: configUi
+
+            configUiModule: configModule
+            configUiComponent: configComponent
+            visible: Plasmoid.configuration.enabledCalendarPlugins.indexOf(pluginId) > -1
+        }
+
+        onObjectAdded: (index, object) => configModel.appendCategory(object)
+        onObjectRemoved: (index, object) => configModel.removeCategory(object)
+    }
 }
diff --git a/applets/calendar/qml/configGeneral.qml b/applets/calendar/qml/configGeneral.qml
index cb28a67bc8..d73948dab6 100644
--- a/applets/calendar/qml/configGeneral.qml
+++ b/applets/calendar/qml/configGeneral.qml
@@ -4,17 +4,44 @@
     SPDX-License-Identifier: GPL-2.0-only OR GPL-3.0-only OR LicenseRef-KDE-Accepted-GPL
 */

+pragma ComponentBehavior: Bound
+
 import QtQuick
 import QtQuick.Controls as QtControls
+import org.kde.plasma.plasmoid
+import org.kde.plasma.workspace.calendar as PlasmaCalendar
 import org.kde.kirigami as Kirigami
 import org.kde.kcmutils as KCM

-KCM.SimpleKCM {
+KCM.ScrollViewKCM {
     id: root
+
+    signal configurationChanged()
+
     property alias cfg_showWeekNumbers: showWeekNumbers.checked
     property string cfg_compactDisplay
+    property bool unsavedChanges: false
+
+    extraFooterTopPadding: true
+
+    function saveConfig() {
+        Plasmoid.configuration.enabledCalendarPlugins = eventPluginsManager.enabledPlugins;
+        Plasmoid.configuration.writeConfig()
+        unsavedChanges = false
+    }
+
+    function checkUnsavedChanges() {
+        root.unsavedChanges = !(Plasmoid.configuration.enabledCalendarPlugins.every(entry => eventPluginsManager.enabledPlugins.includes(entry)) && eventPluginsManager.enabledPlugins.every(entry => Plasmoid.configuration.enabledCalendarPlugins.includes(entry)))
+    }
+
+    header: Kirigami.FormLayout {
+        PlasmaCalendar.EventPluginsManager {
+            id: eventPluginsManager
+            Component.onCompleted: {
+                populateEnabledPluginsList(Plasmoid.configuration.enabledCalendarPlugins);
+            }
+        }

-    Kirigami.FormLayout {
         QtControls.CheckBox {
             id: showWeekNumbers

@@ -42,5 +69,48 @@ KCM.SimpleKCM {
             checked: root.cfg_compactDisplay == "w"
             onCheckedChanged: if (checked) root.cfg_compactDisplay = "w"
         }
+
+        Item {
+            Kirigami.FormData.isSection: true
+        }
+    }
+
+    view: ListView {
+        id: pluginListView
+        activeFocusOnTab: true
+        model: eventPluginsManager.model
+        header: Kirigami.InlineViewHeader {
+            text: i18nc("@title:column", "Available Add-Ons")
+            width: pluginListView.width
+        }
+        headerPositioning: ListView.OverlayHeader
+        delegate: QtControls.CheckDelegate {
+            id: delegate
+            required property var model
+            width: pluginListView.width
+            checked: model.checked
+            text: model.display
+            property string subtitle: model.toolTip
+            icon.source: model.decoration
+
+            Accessible.onPressAction: {
+                toggle();
+                clicked();
+            }
+
+            onClicked: {
+                //needed for model's setData to be called
+                model.checked = checked;
+                root.checkUnsavedChanges();
+            }
+
+            contentItem: Kirigami.IconTitleSubtitle {
+                width: delegate.availableWidth
+                icon: icon.fromControlsIcon(delegate.icon)
+                title: delegate.text
+                subtitle: delegate.subtitle
+                selected: delegate.highlighted || delegate.pressed
+            }
+        }
     }
 }
diff --git a/applets/calendar/qml/main.qml b/applets/calendar/qml/main.qml
index c536afd1ca..d79bb58d35 100644
--- a/applets/calendar/qml/main.qml
+++ b/applets/calendar/qml/main.qml
@@ -126,10 +126,17 @@ PlasmoidItem {
             }
         }

+        EventPluginsManager {
+            id: eventPluginsManager
+            enabledPlugins: Plasmoid.configuration.enabledCalendarPlugins
+        }
+
         MonthView {
             id: calendar
             today: clockSource.dateTime
             showWeekNumbers: Plasmoid.configuration.showWeekNumbers
+            eventPluginsManager: eventPluginsManager
+            headerSubtitle: calendar.currentDateAuxilliaryText

             anchors.fill: parent
         }
diff --git a/components/calendar/qml/MonthView.qml b/components/calendar/qml/MonthView.qml
index 619852a770..ccfee4a834 100644
--- a/components/calendar/qml/MonthView.qml
+++ b/components/calendar/qml/MonthView.qml
@@ -60,7 +60,7 @@ Item {
         if (root.currentDate.toDateString() === root.previousToday.toDateString()
                 && root.today.toDateString() !== root.previousToday.toDateString()) {
             root.currentDate = root.today;
-            root.currentDateAuxilliaryText = root.todayAuxilliaryText;
+            root.currentDateAuxilliaryText = Qt.binding(() => root.todayAuxilliaryText);
         }
         root.previousToday = root.today;
     }
@@ -135,7 +135,7 @@ Item {
     function resetToToday() {
         calendarBackend.resetToToday();
         root.currentDate = root.today;
-        root.currentDateAuxilliaryText = root.todayAuxilliaryText;
+        root.currentDateAuxilliaryText = Qt.binding(() => root.todayAuxilliaryText);
         swipeView.currentIndex = 0;
     }

